def time_to_minutes(h, m):
    return h * 60 + m

def is_available(free_slots, start_min, end_min):
    """Check if a time range is fully covered by free slots"""
    for fs_start_h, fs_start_m, fs_end_h, fs_end_m in free_slots:
        fs_start = time_to_minutes(fs_start_h, fs_start_m)
        fs_end = time_to_minutes(fs_end_h, fs_end_m)
        if fs_start <= start_min and end_min <= fs_end:
            return True
    return False

