        return False

    # Olivia: needs 10 min free before, within work hours
    if start - 10 < 540:  # 9:00
        return False
    if not is_available(olivia_free[day], start - 10, start):
        return False
    if not is_available(olivia_free[day], start, end):
        return False

    # Rachel
    if not is_available(rachel_free[day], start, end):
        return False

    # Rachel: max 60 min on Mon/Thu
    if day in ['Monday', 'Thursday'] and duration > 60:
        return False

    return True

